using System;using System.Collections.Generic;public class Solution{List<IList<string>>o=new();void F(int n,int r,int c,int d1,int d2,char[][]b){if(r==n){var x=new List<string>();foreach(var q in b)x.Add(new string(q));o.Add(x);return;}int a=((1<<n)-1)&~(c|d1|d2);while(a!=0){int bit=a&-a;a-=bit;int col=0;while((1<<col)!=bit)col++;b[r][col]='Q';F(n,r+1,c|bit,(d1|bit)<<1,(d2|bit)>>1,b);b[r][col]='.';}}public IList<IList<string>> SolveNQueens(int n){var b=new char[n][];for(int i=0;i<n;i++){b[i]=new string('.',n).ToCharArray();}F(n,0,0,0,0,b);return o;}}
